const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && r.id_pedido);
const now = $now;
const p2 = n => String(n).padStart(2, '0');
const hoy = p2(now.day) + '/' + p2(now.month) + '/' + now.year;
const hoyRows = rows.filter(r => String(r.fecha) === hoy);

let total = 0;
const prodQty = {};
const horaCount = {};
for (const r of hoyRows) {
  total += Number(r.total_pago || 0);
  // producto más vendido
  let cart = [];
  try { cart = r.detalles_pedido ? JSON.parse(r.detalles_pedido) : []; } catch (e) { cart = []; }
  for (const it of cart) {
    const nombre = it.nombre || it.id_producto || 'desconocido';
    prodQty[nombre] = (prodQty[nombre] || 0) + Number(it.cantidad || 0);
  }
  // hora pico (por hora entera)
  const h = String(r.hora || '').split(':')[0];
  if (h !== '') horaCount[h] = (horaCount[h] || 0) + 1;
}

let estrella = '—';
let maxQty = 0;
for (const k of Object.keys(prodQty)) { if (prodQty[k] > maxQty) { maxQty = prodQty[k]; estrella = k; } }

let horaPico = '—';
let maxH = 0;
for (const k of Object.keys(horaCount)) { if (horaCount[k] > maxH) { maxH = horaCount[k]; horaPico = k; } }
if (horaPico !== '—') { horaPico = p2(horaPico) + ':00 - ' + p2((Number(horaPico) + 1) % 24) + ':00'; }

const texto = 'Reporte diario DeliveryBot\n' +
  'Fecha: ' + hoy + '\n' +
  'Total vendido: $' + total.toLocaleString('es-CO') + '\n' +
  'Pedidos: ' + hoyRows.length + '\n' +
  'Producto estrella: ' + estrella + '\n' +
  'Hora pico: ' + horaPico;

return [{ json: { fecha: hoy, total_vendido: total, num_pedidos: hoyRows.length, producto_estrella: estrella, hora_pico: horaPico, texto } }];
